const prev = $('Un envio').item.json;
const link = $('Pedir link').item.json;
const estado = String(prev.estado || '');
const tipo = String(prev.tipo || '');
const linkUrl = String(link.linkUrl || '');
const detalle = String(prev.ultimoError || '');
let asunto = 'ARCA ' + tipo + ' urgente sin confirmar (' + estado + ')';
let texto = [
  'Un alta, baja o anulación urgente de ARCA no se confirmó.',
  '',
  'Empresa: ' + (prev.empresaId || ''),
  'Envío: ' + (prev.envioId || ''),
  'Estado: ' + estado,
  'Minutos: ' + (prev.minutos ?? ''),
  'Enviable: ' + prev.enviable,
  'Detalle: ' + detalle,
  '',
  'Carga manual, un solo uso, vence a las 48 h:',
  linkUrl,
].join('\n');
if (estado === 'VERIFICAR') {
  asunto = 'ARCA ' + tipo + ' enviado pero no aparece en ARCA';
  texto = [
    'Enviado pero no aparece en ARCA.',
    '',
    'El alta figura enviada y, pasadas 48 h, no aparece la relación eventual (mod. 012).',
    'Revisar el Domicilio Fiscal Electrónico.',
    '',
    'Empresa: ' + (prev.empresaId || ''),
    'Envío: ' + (prev.envioId || ''),
    'Estado: VERIFICAR',
    '',
    'Carga manual, un solo uso, vence a las 48 h:',
    linkUrl,
  ].join('\n');
} else if (estado === 'MANUAL' && tipo === 'ANULACION') {
  asunto = 'ARCA anulación MANUAL';
  texto = [
    'La anulación urgente quedó en MANUAL. Hay que hacerla en la web de ARCA.',
    '',
    'Empresa: ' + (prev.empresaId || ''),
    'Envío: ' + (prev.envioId || ''),
    'Estado: MANUAL',
    'Detalle: ' + detalle,
    '',
    'Carga manual, un solo uso, vence a las 48 h:',
    linkUrl,
  ].join('\n');
}
const filas = [];
for (const mail of $json.mails || []) {
  if (!mail) continue;
  filas.push({ json: { mail, asunto, texto, linkUrl, tipo, estado, envioId: prev.envioId } });
}
return filas;
